import unittest
from subject import route


class RouteTests(unittest.TestCase):
    # 判準來源：題目規格；預期值依規格人工推導後固定為字面值。

    def test_confirmed_examples(self):
        # 已確認例子：route(0,True)=weekday、route(5,True)=weekend
        self.assertEqual(route(0, True), "weekday")
        self.assertEqual(route(5, True), "weekend")

    def test_weekday_boundary_4(self):
        # 規格：day 0..4 -> weekday；抓 >=4 誤判成 weekend 的邊界錯
        self.assertEqual(route(4, True), "weekday")

    def test_weekday_middle(self):
        for d in (1, 2, 3):
            self.assertEqual(route(d, True), "weekday")

    def test_weekend_upper_6(self):
        # 規格：day 5..6 -> weekend；抓上界 6 處理錯
        self.assertEqual(route(6, True), "weekend")

    def test_disabled_paused_all_valid_days(self):
        # 規格：合法 day 且 enabled=False -> paused（平日、週末都要）
        for d in (0, 4, 5, 6):
            self.assertEqual(route(d, False), "paused")

    def test_invalid_below_range(self):
        # -1 為非法；抓下界守衛遺漏
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(-1, True)

    def test_invalid_above_range(self):
        # 7 為非法；抓上界守衛遺漏（否則會回 weekend）
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route(7, True)

    def test_invalid_string_day(self):
        # 非整數拒絕；理由需為 invalid-day（非 TypeError 比較錯）
        with self.assertRaisesRegex(ValueError, "^invalid-day$"):
            route("3", True)

    def test_day_validated_before_enabled(self):
        # 規格：先驗 day；enabled=False 時非法 day 仍須拒絕，不可回 paused
        for bad in (-1, 7, "0"):
            with self.assertRaisesRegex(ValueError, "^invalid-day$"):
                route(bad, False)
